function t(key){const v=DICT[lang][key]??DICT.es[key]??key;return typeof v==='function'?v(''):v}
function t1(key,arg){const v=DICT[lang][key]??DICT.es[key]??key;return typeof v==='function'?v(arg):v}
function setLang(l){lang=l==='en'?'en':'es';localStorage.setItem(LANG_KEY,lang);document.documentElement.lang=lang;applyLang()}
function applyLang(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});document.querySelectorAll('[data-i18n-ph]').forEach(el=>{el.placeholder=t(el.dataset.i18nPh)});if(typeof refreshHUD==='function')refreshHUD()}
